.weekday-picker label,.place-picker label,.inline-check { display: flex; align-items: center; gap: 8px; min-height: 36px; }
.place-picker label { flex-basis: 100%; }
.delivery-list { list-style: none; padding: 0; }.delivery-list li { margin-block: 12px; }
.reminder-editor,.geofence-rule { min-width: 0; }.reminder-editor :is(input,select,textarea) { min-width: 0; max-width: 100%; }.reminder-editor h3:focus { outline: none; }.editor-discard { border: 1px solid var(--line-strong); border-radius: var(--radius-sm); padding: 12px; }.editor-discard h4 { margin: 0; }.presence-summary { margin-block: 12px; }.presence-summary p { margin-block: 6px; }
legend { padding-inline: 6px; color: var(--muted); font-size: .86rem; }
</style>
